"use client";
import { useState } from "react";
type Product = { id: string; name: string; price: number };
export default function AtelierPage() {
  const [products, setProducts] = useState<Product[]>([]);
  const [message, setMessage] = useState("Clique sur Charger");
  const [loading, setLoading] = useState(false);
  async function load() {
    setLoading(true);
    setMessage("Chargement…");
    try {
      const response = await fetch("/api/atelier-demo", {
        cache: "no-store", signal: AbortSignal.timeout(10000),
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data: unknown = await response.json();
      if (!Array.isArray(data) || !data.every(p => p &&
        typeof p.id === "string" && typeof p.name === "string" &&
        typeof p.price === "number")) throw new Error("Réponse invalide");
      setProducts(data);
      setMessage(data.length ? "Produits chargés" : "Aucun produit");
    } catch { setMessage("Impossible de charger. Réessaie."); }
    finally { setLoading(false); }
  }
  return <main>
    <button disabled={loading} onClick={load}>Charger</button>
    <p role="status">{message}</p>
    {products.map(p => <p key={p.id}>{p.name} : {p.price} MAD</p>)}
  </main>;
}
